    FlowTraceRecords = coalesce(FlowTraceRecords, 0), Invalid = coalesce(Invalid, 0), LastFlowTrace, LastRuleLog
| order by case(FlowTrace == 'Off', 0, FlowTrace == 'Unknown', 1, 2) asc, FirewallId asc

